/* phase-381 W4 — the graph entry points must be DECLARED, callable, and
 * spelled the way a C user will type them.
 *
 * Why this probe exists, concretely: the first version of these five was
 * generated by a Rust macro. It compiled, `just check c` passed, and cbindgen
 * emitted NOTHING for them — cbindgen does not expand macros, so four of the
 * five entry points had no header declaration and were uncallable from C. The
 * Rust side was green the whole time. Taking function POINTERS here is what
 * turns that into a build failure instead of a discovery by a user.
 *
 * Pointers, not calls: this is a syntax-only TU with no executor to pass, and
 * the question is whether the declarations exist with the right shapes.
 */

#include <rclc/rclc.h>
#include <stddef.h>

/* The two visitor typedefs are part of the surface — a caller cannot write a
 * visitor without them, and they are what a macro-generated entry point would
 * also have failed to emit. */
static bool visit_node(void* ctx, const char* name, const char* ns, const char* enclave) {
    (void)ctx;
    (void)name;
    (void)ns;
    /* NULL is the contract's "this backend tracks no enclave", which is what
     * lets one call answer both upstream `rmw_get_node_names` forms. A caller
     * must be able to test for it. */
    return enclave == NULL;
}

static bool visit_names_and_types(void* ctx, const char* name, const char* const* types,
                                  size_t types_count) {
    (void)ctx;
    (void)name;
    (void)types;
    /* 0 is legal on a partially discovered graph. */
    return types_count >= 0u;
}

int main(void) {
    /* Each pointer fails to compile if the declaration is missing or its
     * signature drifted. */
    rcl_ret_t (*p_node_names)(struct rclc_executor_t*, rclc_node_visit_fn, void*) =
        rclc_executor_get_node_names;
    rcl_ret_t (*p_topics)(struct rclc_executor_t*, rclc_names_and_types_visit_fn, void*) =
        rclc_executor_get_topic_names_and_types;
    rcl_ret_t (*p_services)(struct rclc_executor_t*, rclc_names_and_types_visit_fn, void*) =
        rclc_executor_get_service_names_and_types;
    rcl_ret_t (*p_count_pub)(struct rclc_executor_t*, const char*, size_t*) =
        rclc_executor_count_publishers;
    rcl_ret_t (*p_count_sub)(struct rclc_executor_t*, const char*, size_t*) =
        rclc_executor_count_subscribers;
    /* Issue 1978 — the Jazzy service twins (`rcl_count_clients` /
     * `rcl_count_services`), same shape. */
    rcl_ret_t (*p_count_cli)(struct rclc_executor_t*, const char*, size_t*) =
        rclc_executor_count_clients;
    rcl_ret_t (*p_count_srv)(struct rclc_executor_t*, const char*, size_t*) =
        rclc_executor_count_services;

    /* phase-381 W3/W4 — the six per-node and per-topic forms.
     *
     * `rclc_executor_get_subscriber_names_and_types_by_node`, NOT
     * `subscription`: the C surface takes rcl's vocabulary
     * (`rcl_get_subscriber_names_and_types_by_node`), while C++ and Rust take
     * rclcpp's and rclrs's `subscription`. If someone "aligns" the three, this
     * line stops compiling — which is the point of naming it here. */
    rcl_ret_t (*p_pub_by_node)(struct rclc_executor_t*, const char*, const char*,
                               rclc_names_and_types_visit_fn, void*) =
        rclc_executor_get_publisher_names_and_types_by_node;
    rcl_ret_t (*p_sub_by_node)(struct rclc_executor_t*, const char*, const char*,
                               rclc_names_and_types_visit_fn, void*) =
        rclc_executor_get_subscriber_names_and_types_by_node;
    rcl_ret_t (*p_srv_by_node)(struct rclc_executor_t*, const char*, const char*,
                               rclc_names_and_types_visit_fn, void*) =
        rclc_executor_get_service_names_and_types_by_node;
    rcl_ret_t (*p_cli_by_node)(struct rclc_executor_t*, const char*, const char*,
                               rclc_names_and_types_visit_fn, void*) =
        rclc_executor_get_client_names_and_types_by_node;
    rcl_ret_t (*p_pubs_info)(struct rclc_executor_t*, const char*, rclc_endpoint_info_visit_fn,
                             void*) = rclc_executor_get_publishers_info_by_topic;
    rcl_ret_t (*p_subs_info)(struct rclc_executor_t*, const char*, rclc_endpoint_info_visit_fn,
                             void*) = rclc_executor_get_subscriptions_info_by_topic;

    (void)p_pub_by_node;
    (void)p_sub_by_node;
    (void)p_srv_by_node;
    (void)p_cli_by_node;
    (void)p_pubs_info;
    (void)p_subs_info;

    /* phase-444 — the matched-count pair, on the ENTITY receiver upstream
       uses (`rclc_publisher_get_subscription_count`). Declared here rather
       than in their own TU because the weakening is in the SIGNATURE: an
       executor parameter rcl does not take, and a `rcl_ret_t` return in
       place of rcl's `rcl_ret_t`-plus-out-parameter shape. A pointer pins
       both; a call would not. */
    rcl_ret_t (*p_pub_sub_count)(const struct rcl_publisher_t*, struct rclc_executor_t*, size_t*) =
        rclc_publisher_get_subscription_count;
    rcl_ret_t (*p_sub_pub_count)(const struct rcl_subscription_t*, struct rclc_executor_t*,
                                 size_t*) = rclc_subscription_get_publisher_count;

    (void)p_pub_sub_count;
    (void)p_sub_pub_count;

    /* And the visitor typedefs must accept a conforming function. */
    rclc_node_visit_fn nv = visit_node;
    rclc_names_and_types_visit_fn ntv = visit_names_and_types;

    (void)p_node_names;
    (void)p_topics;
    (void)p_services;
    (void)p_count_pub;
    (void)p_count_sub;
    (void)p_count_cli;
    (void)p_count_srv;
    (void)nv;
    (void)ntv;
    return 0;
}
